require __DIR__.'/../config.php';if(admin_count()===0){header('Location: setup.php');exit;}$err='';$success='';$username='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{if(recovery_locked('admin'))throw new RuntimeException('Muitas tentativas incorretas. Aguarde 15 minutos e tente novamente.');$name=trim((string)($_POST['full_name']??''));$birth=trim((string)($_POST['birth_date']??''));$cpf=normalize_cpf((string)($_POST['cpf']??''));$pass=(string)($_POST['password']??'');$pass2=(string)($_POST['password2']??'');if($name===''||$birth===''||!cpf_valid($cpf))throw new RuntimeException('Não foi possível confirmar os dados informados.');if(strlen($pass)<10)throw new RuntimeException('A nova senha deve ter pelo menos 10 caracteres.');if($pass!==$pass2)throw new RuntimeException('As novas senhas não coincidem.');$st=db()->prepare("SELECT * FROM admins WHERE birth_date=? AND cpf=?");$st->execute([$birth,$cpf]);$found=null;foreach($st->fetchAll() as $candidate){if(recovery_normalize_name((string)$candidate['display_name'])===recovery_normalize_name($name)){$found=$candidate;break;}}if(!$found){recovery_register_failure('admin');throw new RuntimeException('Não foi possível confirmar os dados informados.');}db()->prepare("UPDATE admins SET password_hash=? WHERE id=?")->execute([password_hash($pass,PASSWORD_DEFAULT),(int)$found['id']]);recovery_clear('admin');$username=(string)$found['username'];$success='Senha redefinida com sucesso.';}catch(Throwable $e){$err=$e->getMessage();}}
$logo=setting('logo_path','assets/brasao_bamab_2026.png');$primary=valid_hex_color(setting('primary_color','#090909'),'#090909');$gold=valid_hex_color(setting('secondary_color','#c99a34'),'#c99a34');$dark=valid_hex_color(setting('dark_color','#050505'),'#050505');$light=valid_hex_color(setting('light_color','#ededed'),'#ededed');
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="noindex,nofollow,noarchive"><title>Redefinir senha do Admin — BAMAB</title><link rel="stylesheet" href="../<?=e(app_asset('assets/admin.css'))?>"><style>:root{--site-primary:<?=e($primary)?>;--site-gold:<?=e($gold)?>;--site-dark:<?=e($dark)?>;--site-light:<?=e($light)?>}</style></head><body class="auth-body bamab-auth-body"><main class="auth-card bamab-auth-card recovery-card"><img class="auth-crest" src="../<?=e($logo)?>" alt="Brasão BAMAB"><div class="auth-band-name"><strong>BAMAB</strong><small>RECUPERAÇÃO DO ADMIN</small></div><div class="auth-greeting"><span><?=e(bamab_greeting())?>!</span><h1>Redefinir senha</h1><p>Confirme sua identidade com nome, nascimento e CPF.</p></div><?php if($success):?><div class="alert ok"><?=e($success)?><?php if($username):?><br>Seu usuário de acesso é: <strong><?=e($username)?></strong><?php endif;?></div><a class="primary forgot-success-button" href="login.php?reset=1">VOLTAR PARA O LOGIN</a><?php else:?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Nome completo<input name="full_name" required autocomplete="name"></label><div class="grid2"><label>Data de nascimento<input type="date" name="birth_date" required></label><label>CPF<input name="cpf" inputmode="numeric" required></label></div><label>Nova senha<input type="password" name="password" minlength="10" required autocomplete="new-password"></label><label>Confirmar nova senha<input type="password" name="password2" minlength="10" required autocomplete="new-password"></label><button class="primary">REDEFINIR MINHA SENHA</button></form><?php endif;?><a class="auth-back-link" href="login.php">← Voltar ao login do Admin</a></main></body></html>
